import { generateBaseURL, options } from '@/utils';
import { Box, Heading, Input, InputGroup, NativeSelect } from '@chakra-ui/react';
import { LuSearch } from 'react-icons/lu';
import React from 'react';
import { useNavigate, useSearchParams } from 'react-router';

const Result = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const query = searchParams.get('query');
  const selectedCategory = searchParams.get('category');
  const [category, setCategory] = React.useState(selectedCategory);
  const [queryInput, setQueryInput] = React.useState(query);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    navigate(`/search?query=${queryInput}&category=${category}`);
  };

  React.useEffect(() => {
    const baseUrl = generateBaseURL(selectedCategory || 'web');
    const fetchData = async () => {
      if (process.env.NODE_ENV === 'development') {
        const response = await fetch(baseUrl);
        const data = await response.json();
        console.log(data);
      } else {
        const response = await fetch(baseUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ query: queryInput }),
        });
        const data = await response.json();
        console.log(data);
      }
    };
    fetchData();
  }, [selectedCategory]);

  return (
    <>

        {/* SelectBy */}


             {
                setCategory(e.target.value);
                navigate(`/search?query=${queryInput}&category=${e.target.value}`);
              }}
            >
              Search By
              {options.map((option, index) => (

                  {option.label}

              ))}




        {/*  */}

          PN Search

            <InputGroup
              flex="1"
              startElement={}
            >
               setQueryInput(e.target.value)}
                fontSize="1rem"
              />




    </>
  );
};

export default Result;



